11	
12	/* The readout cycled by a tap. INFO_NAME is the name badge: the wearer's name
13	 * in the middle of the screen, in place of the hack's name. */
14	typedef enum { INFO_NONE, INFO_NAME, INFO_FPS, INFO_BATTERY } OverlayInfo;
15	
16	/* Decides what text to draw over the hack: its name for a few seconds after it
17	 * starts, and optionally the frame rate or battery level. Holds no drawing
18	 * code, so it can be tested on the host. Times are millisecond counter values
19	 * that may wrap. */
20	typedef struct {
21	  uint32_t name_ms;
22	  uint32_t name_started_ms;
23	  uint32_t fps_window_start_ms;
24	  uint32_t fps_window_frames;
25	  float fps;
26	  bool name_armed;
27	  bool has_fps;
28	  OverlayInfo info;
29	  int battery_pct;
30	  bool drawn_name;
31	  OverlayInfo drawn_info;
32	  int drawn_battery_pct;
33	} Overlay;
34	
35	void overlay_init(Overlay *o, uint32_t name_ms);
36	
37	/* A hack (re)started: show its name again and measure its frame rate afresh.
38	 * The chosen readout is kept. */
39	void overlay_hack_started(Overlay *o, uint32_t now_ms);
40	
41	/* Next readout: nothing, badge, fps, battery, nothing... Starts at nothing. */
42	void overlay_cycle_info(Overlay *o);
43	
44	/* A battery reading in percent. Above 100 is clamped; a negative value means
45	 * the read failed, and the last good level stays. */
46	void overlay_set_battery(Overlay *o, int pct);
47	
48	/* One frame was drawn at now_ms. */
49	void overlay_frame(Overlay *o, uint32_t now_ms);
50	
51	/* The hack's name: for a few seconds after a start, except in badge mode. */
52	bool overlay_name_visible(const Overlay *o, uint32_t now_ms);
53	bool overlay_fps_visible(const Overlay *o);
54	bool overlay_badge_visible(const Overlay *o);
55	bool overlay_battery_visible(const Overlay *o);
56	
57	/* "12.3 fps", or "-- fps" until a full second of frames has been measured.
58	 * Always NUL-terminated and truncated to fit. */
59	void overlay_fps_text(const Overlay *o, char *buf, size_t size);
60	
61	/* "91%", or "--%" until a level has been read. Always NUL-terminated and
62	 * truncated to fit. */
63	void overlay_battery_text(const Overlay *o, char *buf, size_t size);
64	
65	/* The overlay on screen no longer matches what should be shown (the name
66	 * expired, the readout changed or the shown battery level moved), so the frame needs repainting. Call
67	 * overlay_drawn after painting. */
68	bool overlay_wants_redraw(const Overlay *o, uint32_t now_ms);
69	void overlay_drawn(Overlay *o, uint32_t now_ms);
70	
71	#ifdef __cplusplus
72	}
73	#endif
74	
75	#endif
