127	/* The outline is a black copy of the text at every offset within `outline`
128	 * pixels, which grows with the text size so it stays visible. */
129	static void stampText(Patch *p, const char *text, int cx, int cy,
130	                      const lgfx::IFont *font, int scale = 1) {
131	  int outline = 1 + scale / 4;
132	  int margin = outline + 1;
133	  stamp.setFont(font);
134	  stamp.setTextSize(scale);
135	  stamp.setTextDatum(middle_center);
136	  int w = stamp.textWidth(text) + 2 * margin;
137	  int h = stamp.fontHeight() + 2 * margin;
138	  p->w = w < kSize ? w : kSize;
139	  p->h = h < kPatchMaxH ? h : kPatchMaxH;
140	  p->x = cx - p->w / 2;
141	  p->y = cy - p->h / 2;
142	  canvas_copy_rect(&canvas, p->x, p->y, p->w, p->h, p->saved);
143	  stamp.setTextColor(0x000000);
144	  for (int dy = -outline; dy <= outline; dy++)
145	    for (int dx = -outline; dx <= outline; dx++)
146	      if (dx || dy) stamp.drawString(text, cx + dx, cy + dy);
147	  stamp.setTextColor(0xFFFFFF);
148	  stamp.drawString(text, cx, cy);
149	  stamp.setTextSize(1);
