201	/* Returns true if a button switched hacks. */
202	static bool pollButtons() {
203	  bool switched = false;
204	  uint32_t pressedAt = 0;
205	  if (button_latch_take(&latchA, &pressedAt)) {
206	    runner_next(runner);
207	    switched = true;
208	  }
209	  if (button_latch_take(&latchB, &pressedAt)) {
210	    runner_prev(runner);
211	    switched = true;
212	  }
213	  if (switched) {
214	    Serial.printf("switch -> %s press_waited=%ums heap=%u psram=%u\n",
215	                  g_hacks[runner_index(runner)]->name,
216	                  (unsigned)(millis() - pressedAt),
217	                  (unsigned)ESP.getFreeHeap(),
218	                  (unsigned)heap_caps_get_free_size(MALLOC_CAP_SPIRAM));
219	    hackStarted();
220	  }
221	  return switched;
222	}
