224	/* Returns true if the timer moved on to the next hack. */
225	static bool pollRotation() {
226	  if (!rotation_due(&rotation, millis())) return false;
227	  runner_next(runner);
228	  Serial.printf("rotate -> %s heap=%u psram=%u\n",
229	                g_hacks[runner_index(runner)]->name, (unsigned)ESP.getFreeHeap(),
230	                (unsigned)heap_caps_get_free_size(MALLOC_CAP_SPIRAM));
231	  hackStarted();
232	  return true;
233	}
