235	/* A tap anywhere cycles the readout: nothing, name badge, fps, battery. Call
236	 * right after M5.update(), which is the only place the touch edge is
237	 * recorded. */
238	static void pollTouch() {
239	  if (M5.Touch.getDetail().wasPressed()) overlay_cycle_info(&overlay);
240	}
241	
242	/* The fuel gauge is read over I2C through the power chip, which can fail the
243	 * first transaction after idle, so read it every 30 s, not every frame. A
244	 * failed read is negative and the overlay keeps the last good level. */
245	static void pollBattery() {
246	  static uint32_t lastReadMs;
247	  static bool readOnce;
248	  uint32_t now = millis();
249	  if (readOnce && now - lastReadMs < kBatteryEveryMs) return;
250	  readOnce = true;
251	  lastReadMs = now;
252	  overlay_set_battery(&overlay, M5.Power.getBatteryLevel());
253	}
254	
255	void setup() {
256	  auto cfg = M5.config();
257	  M5.begin(cfg);
258	  Serial.begin(115200);
259	  M5.Display.setSwapBytes(false);
260	
261	  button_latch_init(&latchA, kButtonSettleMs);
262	  button_latch_init(&latchB, kButtonSettleMs);
263	  xTaskCreatePinnedToCore(buttonTask, "buttons", 2048, nullptr, 2, nullptr, 0);
264	
265	  if (canvas_init(&canvas, kSize, kSize, ps_malloc) != 0)
266	    halt("PSRAM alloc failed");
267	  stamp.setBuffer(canvas.px, kSize, kSize, 16);
268	  namePatch.saved = (uint16_t *)ps_malloc(kSize * kPatchMaxH * sizeof(uint16_t));
269	  infoPatch.saved = (uint16_t *)ps_malloc(kSize * kPatchMaxH * sizeof(uint16_t));
270	  if (!namePatch.saved || !infoPatch.saved) halt("PSRAM alloc failed");
271	  runner = runner_create(&canvas);
272	  if (!runner) halt("hack start failed");
273	  int first = start_pick_index(g_hacks, g_hack_count, kForcedStart, esp_random());
274	  if (kForcedStart && start_find_hack(g_hacks, g_hack_count, kForcedStart) < 0)
275	    Serial.printf("START_HACK \"%s\" not found, starting at random\n",
276	                  kForcedStart);
277	  if (runner_start(runner, first) != 0) halt("hack start failed");
278	  overlay_init(&overlay, kNameShownMs);
279	  rotation_init(&rotation, kRotateMs, millis());
280	  hackStarted();
281	  printStats("boot");
282	  resetStats();
283	}
284	
285	void loop() {
286	  M5.update();
287	  if (!pollButtons()) pollRotation();
288	  pollTouch();
289	  pollBattery();
290	
291	  uint32_t t0 = micros();
292	  unsigned long delayUs = runner_step(runner);
293	  uint32_t t1 = micros();
294	  present();
295	  uint32_t t2 = micros();
296	  frames++;
297	  overlay_frame(&overlay, millis());
298	  stepUs += t1 - t0;
299	  pushUs += t2 - t1;
300	
301	  /* Only the push counts against the delay. A hack's delay is the pause after
302	   * it draws, so a hack that asks for a one-second hold must still get it
303	   * however long its own step took. */
304	  unsigned long waitUsTarget = runner_remaining_delay_us(delayUs, t2 - t1);
305	  uint32_t waitedUs = 0;
306	  bool switched = false;
307	  while (!switched && waitedUs < waitUsTarget) {
308	    uint32_t slice =
309	        waitUsTarget - waitedUs < kSliceUs ? waitUsTarget - waitedUs : kSliceUs;
310	    delayMicroseconds(slice);
311	    waitedUs += slice;
312	    M5.update();
313	    switched = pollButtons() || pollRotation();
314	    if (!switched) {
315	      pollTouch();
316	      pollBattery();
317	    }
318	    if (!switched && overlay_wants_redraw(&overlay, millis())) present();
319	  }
320	  if (!switched) waitUs += micros() - t2;
321	
322	  if (millis() - statsAt >= kStatsEveryMs) {
323	    printStats("run");
324	    resetStats();
325	  }
326	}
